export const localeCookieName = "growvelt-learning-locale";
export const supportedLocales = ["en", "fr", "es"] as const;
export type Locale = (typeof supportedLocales)[number];

export type LanguageOption = { code: Locale; label: string; shortLabel: string };
export const languageOptions: LanguageOption[] = [
  { code: "en", label: "English (Global)", shortLabel: "English" },
  { code: "fr", label: "Français", shortLabel: "Français" },
  { code: "es", label: "Español", shortLabel: "Español" },
];

export function normalizeLocale(value?: string | null): Locale {
  return supportedLocales.includes(value as Locale) ? value as Locale : "en";
}

